import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    degrees = [0] * (n + 1)

    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        adj[u].append((v, w))
        adj[v].append((u, w))
        degrees[u] += 1
        degrees[v] += 1

    q_count = int(next(iterator))
    queries = []
    for _ in range(q_count):
        queries.append(int(next(iterator)))

    if n == 2:
        for l in queries:
            print(2)
        return

    leaves = []
    for i in range(1, n + 1):
        if degrees[i] == 1:
            leaves.append(i)

    dist_to_leaf = [-1] * (n + 1)
    max_dist_from_node = [-1] * (n + 1)

    def bfs(start_nodes):
        dist = [-1] * (n + 1)
        queue = deque()
        for node in start_nodes:
            dist[node] = 0
            queue.append(node)

        while queue:
            u = queue.popleft()
            for v, w in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + w
                    queue.append(v)
        return dist

    dist_to_leaves = bfs(leaves)

    max_dists = [0] * (n + 1)
    for i in range(1, n + 1):
      if dist_to_leaves[i] != -1:
          max_dists[i] = dist_to_leaves[i]
      else:
          max_dists[i] = 0

    q = []
    for i in range(1, n + 1) if len(leaves) > 2 else [leaves[0], leaves[1]]:
        if degrees[i] == 1:
            q.append(i)

    visited = [False] * (n + 1)
    order = []
    while q:
        u = q.pop()
        visited[u] = True
        order.append(u)
        for v, w in adj[u]:
            if not visited[v]:
                degrees[v] -= 1
                if degrees[v] == 1:
                    q.append(v)

    if len(order) < n:
        root = order[-1]
        if len(adj[root]) > 1:
            order.append(root)
        else:
            order.append(root)

    order.reverse()

    dp = [0] * (n + 1)
    min_val = [float('inf')] * (n + 1)
    max_val = [float('-inf')] * (n + 1)

    for u in order:
        if degrees[u] == 1 and u != order[-1]:
            dp[u] = 1
            min_val[u] = max_dists[u]
            max_val[u] = max_dists[u]
        else:
            current_min = float('inf')
            current_max = float('-inf')
            total_children = 0

            for v, w in adj[u]:
                if v == order[order.index(u) - 1] if order.index(u) > 0 else False:
                    continue
                if degrees[v] == 1 and u != order[-1]:
                    pass
                if v in [x for x in order if order.index(x) > order.index(u)]:
                    total_children += dp[v]
                    if min_val[v] != float('inf'):
                        current_min = min(current_min, min_val[v])
                        current_max = max(current_max, max_val[v])

            if current_min == float('inf'):
                dp[u] = 1
                min_val[u] = max_dists[u]
                max_val[u] = max_dists[u]
            else:
                dp[u] = total_children + 1
                min_val[u] = current_min
                max_val[u] = current_max

    ans = []
    for l in queries:
        best = 1
        for i in range(1, n + 1):
            if max_val[i] - min_val[i] <= l:
                best = max(best, dp[i])
        ans.append(best)

    for a in ans:
        print(a)

